import { existsSync as existsSyncFs, mkdirSync as mkdirSyncFs, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

/**
 * senpi 는 `diff/files/prompt-url-widget/tps` 를 agentDir/extensions/<id>.js 에
 * "생성된 shim"으로 깔고, 부팅마다 그 파일을 자기 빌드 경로로 되돌린다. 단 되돌리기는
 * 내용이 자기 배너(`// Generated by …`)로 시작할 때만 한다 (resource-loader
 * `isGeneratedGlobalDefaultExtensionShim`). 배너가 없는 파일은 사용자가 손댄 것으로 보고
 * 그대로 두고, 일반 확장처럼 default export 를 불러 쓴다.
 *
 * 그래서 우리 구현으로 갈아끼우는 정본 통로는 "배너 없는 우리 shim 을 그 자리에 두기"다.
 * node_modules 를 지우는 업데이트에도 살아남고, senpi 기본 tps 는 자동으로 안 실린다
 * (그 자리에 파일이 이미 있으니 생성 대상에서 빠진다).
 */
export const RUBATO_EXTENSION_BANNER =
  "// Owned by rubato-pi. Regenerated on launch from harness/rubato-pi/src/extensions.\n";

/** agentDir/extensions 에 우리가 소유하는 확장들: <shim 파일명> → <레포 안 모듈>. */
export const OWNED_AGENT_EXTENSIONS = {
  "tps.js": join(here, "extensions", "tps.mjs"),
};

export function agentExtensionShim(modulePath) {
  return `${RUBATO_EXTENSION_BANNER}export { default } from ${JSON.stringify(pathToFileURL(modulePath).href)};\n`;
}

/**
 * 매번 덮어쓰지 않고 내용이 다를 때만 쓴다. senpi 의 config-reload 워처는 배너 없는
 * 파일 변경을 곧 확장 리로드로 받으므로, 이유 없는 쓰기는 다른 세션을 흔든다.
 */
export function ensureAgentExtensions(
  agentDir,
  {
    owned = OWNED_AGENT_EXTENSIONS,
    exists = existsSyncFs,
    readFile = readFileSync,
    writeFile = writeFileSync,
    mkdir = mkdirSyncFs,
  } = {},
) {
  const dir = join(agentDir, "extensions");
  const written = [];
  for (const [name, modulePath] of Object.entries(owned)) {
    const target = join(dir, name);
    const shim = agentExtensionShim(modulePath);
    if (exists(target)) {
      let current = "";
      try {
        current = readFile(target, "utf8");
      } catch {
        current = "";
      }
      if (current === shim) continue;
    }
    mkdir(dir, { recursive: true });
    writeFile(target, shim, "utf8");
    written.push(target);
  }
  return written;
}
